"""Patch RequestStatus to add LB_PAUSED state for DyntraLB."""

from enum import Enum


class LBRequestStatus:
    """Load balancing request status extension."""
    LB_PAUSED = "lb_paused"


def apply_nonbsp_request_status_patch():
    """Monkey-patch upstream RequestStatus to include LB_PAUSED."""
    try:
        from vllm.v1.request import RequestStatus
        # 通过 monkey-patch 添加自定义状态到上游枚举
        if not hasattr(RequestStatus, "LB_PAUSED"):
            RequestStatus.LB_PAUSED = "lb_paused"
    except ImportError:
        pass


def is_request_lb_paused(request) -> bool:
    """Check if a request is paused by load balancer."""
    return getattr(request, "status", None) == LBRequestStatus.LB_PAUSED


def pause_request_for_lb(request, scheduler):
    """Pause a request for load balancing migration."""
    request.status = LBRequestStatus.LB_PAUSED
    scheduler._paused_requests.add(request.request_id)


def resume_request_from_lb(request, scheduler):
    """Resume a previously paused request."""
    scheduler._paused_requests.discard(request.request_id)
    request.status = None
